mapper.sql:
AND apr01_reg_date BETWEEN #{c.startDate} AND #{c.closeDate} AND ( apr01_reg_emp_id = #{c.personId} OR #{c.personId} IN ( SELECT apr04_step_emp_id FROM apr04_appr_step WHERE apr04_appr_id = apr01_appr_id UNION SELECT apr13_person_id FROM apr13_person_auth WHERE apr13_appr_id = apr01_appr_id ) )
AND dcr01_class_tree_id IN ( WITH RECURSIVE dcr_tree_down(dcr01_class_tree_id, dcr01_class_tree_nm, dcr01_parent_tree_id, depth, path, cycle) AS ( SELECT a.dcr01_class_tree_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, 1, ARRAY[CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || a.dcr01_class_tree_id], false FROM dcr01_class_tree a WHERE a.dcr01_company_id = #{c.companyId} AND a.dcr01_class_tree_id = #{c.classTreeId} AND a.dcr01_use_yn = 'true' AND a.dcr01_type_cd LIKE #{c.typeCode} UNION ALL SELECT a.dcr01_class_tree_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, b.depth + 1, array_append(b.path, CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || LPAD(CAST(a.dcr01_class_tree_id AS varchar), 15, '0')), a.dcr01_class_tree_nm = any(b.path) FROM dcr01_class_tree a INNER JOIN dcr_tree_down b ON a.dcr01_parent_tree_id = b.dcr01_class_tree_id WHERE a.dcr01_company_id = #{c.companyId} AND a.dcr01_use_yn = 'true' AND a.dcr01_type_cd LIKE #{c.typeCode} AND NOT cycle ) SELECT a.dcr01_class_tree_id FROM dcr_tree_down a )
AND CONCAT(apr01_receive_nm) ILIKE #{c.receiveName}
AND CONCAT(f_emp_kor_nm(apr01_reg_emp_id), apr01_title, dcr01_class_tree_nm, apr01_note) ILIKE #{c.searchText}

mapper.select:
WITH fund_count AS ( SELECT apr03_appr_id , MAX(COALESCE(fnd01_r.fnd01_fund_code_id, fnd01.fnd01_fund_code_id)) AS fund_id , COUNT(DISTINCT apr03_fund_id) AS fund_cnt , STRING_AGG(COALESCE(fnd01_r.fnd01_fund_cd, ' '), ', ') AS fund_real_code_all , STRING_AGG(COALESCE(fnd01.fnd01_fund_cd, ' '), ', ') AS fund_code_all , STRING_AGG(COALESCE(f_get_fund_nm2(fnd01_r.fnd01_fund_code_id, f_today()::date), ' '), ', ') AS fund_real_name_all , STRING_AGG(COALESCE(f_get_fund_nm2(fnd01.fnd01_fund_code_id, f_today()::date), ' '), ', ') AS fund_name_all FROM apr03_relate_fund INNER JOIN fnd01_fund_code fnd01 ON fnd01.fnd01_fund_code_id = apr03_fund_id LEFT JOIN fnd01_fund_code fnd01_r ON fnd01_r.fnd01_fund_code_id = fnd01.fnd01_real_fund_id GROUP BY apr03_appr_id ), adv_count AS ( SELECT apr12_appr_id , MAX(adv02_manage_nm) AS adv_nm , COUNT(DISTINCT apr12_adv_id) AS adv_cnt , STRING_AGG(adv02_manage_cd, ', ') AS adv_code_all , STRING_AGG(adv02_manage_nm, ', ') AS adv_name_all FROM apr12_relate_adv INNER JOIN adv02_account ON adv02_account_id = apr12_adv_id GROUP BY apr12_appr_id ) SELECT apr01_appr_id AS appr_id , ( SELECT CASE WHEN COUNT(*) > 0 THEN 'true' ELSE 'false' END FROM apr50_bookmark WHERE apr50_appr_id = apr01_appr_id AND ( apr50_person_id = #{c.empId} OR apr50_public_yn = 'true' ) ) AS bookmark_yn , apr01_reg_date AS reg_date , emp01_kor_nm AS reg_emp_name , ( CASE WHEN apr01_status_cd = '40' THEN '<' || 'b style=color:#E33E31;' || '>' || f_cdnm('AprStatusCode', apr01_status_cd, apr01_company_id, apr01_reg_date) || '<' || '/b' || '>' WHEN apr01_status_cd = '99' THEN '<' || 'b style=color:#4B81B9;' || '>' || f_cdnm('AprStatusCode', apr01_status_cd, apr01_company_id, apr01_reg_date) || '<' || '/b' || '>' ELSE '<' || 'b style=color:#404040;' || '>' || f_cdnm('AprStatusCode', apr01_status_cd, apr01_company_id, apr01_reg_date) || '<' || '/b' || '>' END ) AS status_name , apr01_title AS title , f_cdnm('AprInOutTypeCode', apr01_inout_cd, apr01_company_id, f_sysdate()) AS in_out_type_name , f_class_tree_nm_allpath(dcr01_class_tree_id) AS class_tree_name , apr01_receive_nm AS receive_name , apr01_stamp_seq AS stamp_seq , CASE WHEN COALESCE(fc.fund_cnt, 0) + COALESCE(ac.adv_cnt, 0) = 0 THEN '' ELSE COALESCE(fc.fund_cnt, 0) + COALESCE(ac.adv_cnt, 0) || '건' END AS relate_display_name , apr01_note AS note FROM apr01_appr INNER JOIN dcr01_class_tree ON dcr01_class_tree_id = apr01_class_tree_id LEFT OUTER JOIN apr10_stamp ON apr10_stamp_id = apr01_stamp_id LEFT OUTER JOIN fund_count fc ON fc.apr03_appr_id = apr01_appr_id LEFT OUTER JOIN adv_count ac ON ac.apr12_appr_id = apr01_appr_id INNER JOIN emp01_person ON emp01_person_id = apr01_reg_emp_id WHERE 1=1 AND apr01_company_id = #{c.companyId}
AND (( ( fc.fund_id IN ( SELECT fnd08_fund_code_id FROM fnd08_org_auth WHERE fnd08_org_code_id = #{c.orgId} AND fnd08_auth_yn = 'true' ) OR fc.fund_id IS NULL ) AND ( 'Y' = CASE WHEN ( SELECT COUNT(*) FROM dcr04_emp_auth WHERE dcr04_class_tree_id = apr01_class_tree_id AND dcr04_person_id = #{c.empId} AND dcr04_retrieve_yn = 'false' ) != 0 THEN 'N' WHEN ( SELECT COUNT(*) FROM dcr03_org_auth WHERE dcr03_class_tree_id = apr01_class_tree_id AND dcr03_org_code_id = #{c.orgId} AND dcr03_retrieve_yn = 'true' ) != 0 THEN 'Y' ELSE 'N' END ) AND ( ( apr01_link_cd IS NULL OR NOT EXISTS ( SELECT 1 FROM sys52_specific_menu_link l WHERE l.sys52_company_id = apr01_company_id AND l.sys52_link_cd = apr01_link_cd ) OR EXISTS ( SELECT 1 FROM sys52_specific_menu_link l INNER JOIN sys50_specific_menu m ON l.sys52_specific_work_cd = m.sys50_specific_work_cd AND m.sys50_company_id = apr01_company_id INNER JOIN sys51_specific_menu_person p ON p.sys51_specific_menu_id = m.sys50_specific_menu_id AND p.sys51_person_id = #{c.empId} WHERE l.sys52_company_id = apr01_company_id AND l.sys52_link_cd = apr01_link_cd ) ) ) ) OR ( #{c.empId} IN ( SELECT apr04_step_emp_id FROM apr04_appr_step WHERE apr04_appr_id = apr01_appr_id ) ) OR ( #{c.empId} IN ( SELECT apr13_person_id FROM apr13_person_auth WHERE apr13_appr_id = apr01_appr_id ) ))
AND COALESCE(apr01_link_cd, ' ') NOT IN ( SELECT sys52_link_cd FROM sys52_specific_menu_link WHERE sys52_company_id = apr01_company_id GROUP BY sys52_link_cd )
AND apr01_class_tree_id IN ( WITH RECURSIVE dcr_tree_down(dcr01_class_tree_id, dcr01_class_tree_nm, dcr01_parent_tree_id, depth, path, cycle) AS ( SELECT a.dcr01_class_tree_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, 1, ARRAY[CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || a.dcr01_class_tree_id], false FROM dcr01_class_tree a WHERE a.dcr01_company_id = #{c.companyId} AND a.dcr01_class_tree_id = #{c.classTreeId} AND a.dcr01_use_yn = 'true' AND a.dcr01_type_cd LIKE #{c.typeCode} UNION ALL SELECT a.dcr01_class_tree_id, a.dcr01_class_tree_nm, a.dcr01_parent_tree_id, b.depth + 1, array_append(b.path, CAST(a.dcr01_parent_tree_id AS varchar) || LPAD(CAST(a.dcr01_seq AS varchar), 10, '0') || a.dcr01_class_tree_cd || LPAD(CAST(a.dcr01_class_tree_id AS varchar), 15, '0')), a.dcr01_class_tree_nm = any(b.path) FROM dcr01_class_tree a INNER JOIN dcr_tree_down b ON a.dcr01_parent_tree_id = b.dcr01_class_tree_id WHERE a.dcr01_company_id = #{c.companyId} AND a.dcr01_use_yn = 'true' AND a.dcr01_type_cd LIKE #{c.typeCode} AND NOT cycle ) SELECT a.dcr01_class_tree_id FROM dcr_tree_down a )
AND CONCAT(apr01_receive_nm) ILIKE #{c.receiveName}
AND apr01_inout_cd ILIKE #{c.aprInoutCode}
AND apr01_status_cd = '30'
AND apr01_status_cd LIKE #{c.aprStatusCode} AND (apr01_status_cd != '99' OR apr01_reg_emp_id = #{c.empId})
AND f_trunc(apr01_reg_date) BETWEEN #{c.startDate} AND #{c.endDate} AND CONCAT( apr01_title , REGEXP_REPLACE(apr01_content, E'<[^>]+>', '', 'gi') , emp01_kor_nm , fc.fund_real_code_all , fc.fund_code_all , fc.fund_real_name_all , fc.fund_name_all , ac.adv_code_all , ac.adv_name_all , apr01_note , apr01_stamp_seq ) ILIKE #{c.searchText} ORDER BY apr01_reg_date DESC , f_class_tree_nm_allpath(dcr01_class_tree_id) COLLATE "ko-KR-x-icu" ASC , apr01_appr_id DESC , apr01_title COLLATE "ko-KR-x-icu" ASC , apr01_status_cd , apr01_effect_date
